    for (const line of adrText(n).split("\n")) {
      const classic = CLASSIC_ROW.exec(line);
      if (classic) {
        out.set(classic[1]!, classic[2]!);
        continue;
      }
      const amendment = AMENDMENT_ROW.exec(line);
      if (amendment && !out.has(amendment[1]!)) out.set(amendment[1]!, null);
    }
  }
