  return useQuery({
    queryKey: p6Keys.notificationChannel(channelKind ?? "", organizationId ?? ""),
    queryFn: () => api.get<T>(p6Paths.notificationChannel(channelKind ?? ""), withOrganization(organizationId)),
    enabled: Boolean(channelKind && organizationId),
