// P5 shell against the REAL API (apps/web/e2e/support/with-stack.sh; T-DG5-FE-A, D-144): the ten area landing pages of
// REQ-S03-007 list the contents master prompt §3 names for each area, with where each lives; the P5 screens of
// FE-B…FE-G are reachable from the navigation and open their delivered screens (T-DG5-FE-G replaced the last
// "not available yet" placeholders: the reader, Branding and the environment screen).
// Every page is checked with axe (no serious or critical violation) and captured as a screenshot. All data is
// SYNTHETIC (seeded dev users).
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { expect, test } from "@playwright/test";
import { expectAccessible, langOf, shot, signIn, tr, trackRequests } from "./support/ui.ts";

const HERE = dirname(fileURLToPath(import.meta.url));

/** The area landing pages and their §3 content ids, read from app/nav.ts's AREA_CONTENTS order via the catalogue. */
const LANDING: readonly { area: string; path: string }[] = [
  { area: "playbook", path: "/playbook" },
  { area: "strategy", path: "/strategy-kpis" },
  { area: "tom", path: "/target-operating-model" },
  { area: "initiatives", path: "/initiatives-roadmaps" },
  { area: "governance", path: "/governance" },
  { area: "risks", path: "/risks-actions" },
  { area: "benefits", path: "/benefits-finance" },
  { area: "change", path: "/change-adoption" },
  { area: "evidence", path: "/evidence-reports" },
  { area: "bau", path: "/bau-improvement" },
];

/** The content ids of one area in catalogue order (the catalogue lists them in §3's order, as AREA_CONTENTS does). */
function contentIds(area: string): string[] {
  const nav = JSON.parse(readFileSync(join(HERE, "..", "src", "i18n", "en", "nav.json"), "utf8")) as {
    contents: Record<string, Record<string, string>>;
  };
  return Object.keys(nav.contents[area] ?? {});
}

// One test per area (D-149): the single 14-page test of T-DG5-FE-A ran at the edge of its 30 s budget (31.7 s in EN
// under load). Every assertion of that test is kept; the timeout is not raised.
for (const { area, path } of LANDING) {
  test(`P5: the ${area} area landing page lists its §3 contents in the project's language (Transformation Office)`, async ({
    page,
  }, info) => {
    const lang = langOf(info);
    const foreign = trackRequests(page);
    await signIn(page, lang, "dev.office");
    await page.goto(path);
    await expect(page.locator("main#main h1")).toHaveText(tr(lang, `nav.areas.${area}.label`));
    await expect(page.getByRole("heading", { level: 2, name: tr(lang, "nav.willContain"), exact: true })).toBeVisible();
    const labels = page.locator(`[data-area-contents='${area}'] > li .area-content__label`);
    await expect(labels).toHaveText(contentIds(area).map((id) => tr(lang, `nav.contents.${area}.${id}`)));
    await expectAccessible(page, lang, `p5-area-${area}`);
    await shot(page, lang, `p5-area-${area}`);
    await expect(page.locator("html")).toHaveAttribute("dir", lang === "ar" ? "rtl" : "ltr");
    await expect(page.locator("body")).not.toContainText(/\bDG[0-7]\b/);
    expect(foreign).toEqual([]);
  });
}

test("P5: the navigation has no planned area, and a P5 screen named on a landing page opens it (Transformation Office)", async ({
  page,
}, info) => {
  const lang = langOf(info);
  const foreign = trackRequests(page);
  await signIn(page, lang, "dev.office");
  const nav = page.getByRole("navigation", { name: tr(lang, "nav.primary"), exact: true });
  // No area carries the "planned" tag (every area has delivered screens; F-DG4-160).
  await expect(nav.getByText(tr(lang, "nav.planned"), { exact: true })).toHaveCount(0);
  // A P5 screen named on a landing page opens it (T-DG5-FE-G: the reader is delivered; F-DG4-160).
  await page.goto("/playbook");
  await page
    .locator("[data-content-item='source']")
    .getByRole("link", { name: tr(lang, "nav.sub.reader"), exact: true })
    .click();
  await expect(page).toHaveURL(/\/playbook\/reader$/);
  await expect(page.locator("main#main h1")).toHaveText(tr(lang, "playbookP5.reader.title"));
  await expect(page.locator("main [data-state='being-built']")).toHaveCount(0);
  await expect(page.locator("form[data-form='reader-search']")).toBeVisible();
  // The P5 entries of the Transformation Office's areas are in the navigation.
  for (const id of ["reader", "myProcedures", "launchPlan", "healthCheck", "reports", "exports", "presentation"])
    await expect(nav.getByRole("link", { name: tr(lang, `nav.sub.${id}`), exact: true })).toBeVisible();
  await expect(page.locator("html")).toHaveAttribute("dir", lang === "ar" ? "rtl" : "ltr");
  await expect(page.locator("body")).not.toContainText(/\bDG[0-7]\b/);
  expect(foreign).toEqual([]);
});

test("P5: Administration lists the P5 configuration screens and opens Branding Settings (administrator)", async ({
  page,
}, info) => {
  const lang = langOf(info);
  const foreign = trackRequests(page);
  await signIn(page, lang, "dev.admin");
  const nav = page.getByRole("navigation", { name: tr(lang, "nav.primary"), exact: true });
  const admin = nav.getByRole("list", { name: tr(lang, "nav.areas.admin.label"), exact: true });
  for (const id of ["formBuilder", "procedureBuilder", "automation", "approvalRoutes", "branding", "demo"])
    await expect(admin.getByRole("link", { name: tr(lang, `nav.sub.${id}`), exact: true })).toBeVisible();
  await admin.getByRole("link", { name: tr(lang, "nav.sub.branding"), exact: true }).click();
  await expect(page).toHaveURL(/\/admin\/branding$/);
  // T-DG5-FE-G: Branding Settings is delivered (F-DG4-160).
  await expect(page.locator("main#main h1")).toHaveText(tr(lang, "playbookP5.branding.title"));
  await expect(page.locator("main [data-state='being-built']")).toHaveCount(0);
#!/usr/bin/env bash
# Runs a command against a REAL local stack for the web journeys (apps/web/e2e):
#   disposable PostgreSQL -> `mth-db migrate` -> `mth-db seed-dev` (SYNTHETIC users) -> API (AUTH_MODE=dev) serving
#   the built SPA from apps/web/dist on http://localhost:3000 (or the port actually used, see below) -> "$@" ->
#   teardown (the cluster is deleted).
# Nothing leaves the machine: no network access is needed. Prerequisite: `pnpm -r build`.
#
# Usage (from the repository root):
#   apps/web/e2e/support/with-stack.sh npx playwright test apps/web/e2e --workers=1
#
# Environment: PGBIN (PostgreSQL bin dir; default: newest /usr/lib/postgresql/*/bin), E2E_PG_PORT or QA_PG_PORT
# (default 24331), E2E_API_PORT (default 3000). Port policy (tests/qa/support/pg-port.sh, F-DG2-310): defaults lie
# below the Linux ephemeral range (32768-60999); a requested port is the STARTING point and, if postgres or the API
# fails to bind (EADDRINUSE, e.g. a client socket in TIME_WAIT), the harness retries on a free port from
# MTH_PORT_POOL (default 25000-31999), up to MTH_PORT_RETRIES (10) times, logging each retry. E2E_PG_STRICT_PORT=1 /
# E2E_API_STRICT_PORT=1 (or MTH_STRICT_PORT=1) turn a conflict into "BLOCKED" (exit 3) instead. The run exports
# E2E_BASE_URL=http://localhost:<port actually used> for Playwright (and APP_BASE_URL/PORT for the API), so two
# stacks on one machine never share a port.
# Exit: the command's status; 3 BLOCKED (missing tool/build, PostgreSQL did not start, ports exhausted); 4 the API did
# not become ready for another reason.
# When run as uid 0 (sandboxes), PostgreSQL is started in a user namespace as uid 1000 because it refuses root.
# The cluster is ALWAYS UTF8 with the C locale (T-DG2-BE9), whatever the shell's LANG/LC_*: without them initdb
# would make a SQL_ASCII cluster, where char_length counts bytes. C (not C.UTF-8) because it exists on every platform
# and sorts by code point independent of the C library version.
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../../../.." && pwd)"
cd "$ROOT"
PGBIN="${PGBIN:-$(ls -d /usr/lib/postgresql/*/bin 2>/dev/null | sort -V | tail -1)}"
PG_PORT="${E2E_PG_PORT:-${QA_PG_PORT:-24331}}"
API_PORT="${E2E_API_PORT:-3000}"
# shellcheck source=../../../../tests/qa/support/pg-port.sh
. "$ROOT/tests/qa/support/pg-port.sh"
WORK="$(mktemp -d "${TMPDIR:-/tmp}/mth-web-e2e.XXXXXX")"
chmod 777 "$WORK"
PG_PID=""
API_PID=""

as_pg() {
  if [ "$(id -u)" = "0" ]; then unshare --user --map-user=1000 --map-group=1000 "$@"; else "$@"; fi
}
cleanup() {
  [ -n "$API_PID" ] && kill "$API_PID" 2>/dev/null || true
  if [ -n "$PG_PID" ]; then
    kill -INT "$PG_PID" 2>/dev/null || true
    for _ in $(seq 1 50); do kill -0 "$PG_PID" 2>/dev/null || break; sleep 0.1; done
    kill -KILL "$PG_PID" 2>/dev/null || true
  fi
  rm -rf "$WORK"
}
trap cleanup EXIT

[ -x "$PGBIN/initdb" ] || { echo "BLOCKED: PostgreSQL binaries not found (set PGBIN)"; exit 3; }
[ -f apps/api/dist/main.js ] && [ -f apps/web/dist/index.html ] || { echo "BLOCKED: run 'pnpm -r build' first"; exit 3; }

as_pg "$PGBIN/initdb" -D "$WORK/pg" -U postgres --auth=trust --encoding=UTF8 --locale=C >/dev/null
mth_pg_start "$PGBIN" "$WORK/pg" "$WORK/pg.log" "$PG_PORT" E2E_PG_STRICT_PORT PG_PID || exit 3
PG_PORT="$MTH_PG_PORT"
ADMIN_URL="postgresql://postgres@127.0.0.1:${PG_PORT}/postgres"
psql "$ADMIN_URL" -qAtc "select 1" >/dev/null || { echo "BLOCKED: disposable PostgreSQL did not start"; exit 3; }

